import { getCookie } from "cookies-next";
import { apiClient, ApiError } from "@/lib/apiClient";

/**
 * Profil güncelleme — apiv3 `POST /b2c/profile` (Sanctum, auth-token-v3).
 * Sanctum token tarayıcıda apiClient ile proxy üzerinden gönderilir.
 *
 * Bileşenler hem başarı ({success:true}), hem "şifre yanlış" ({success:false}, 200),
 * hem de 422 doğrulama ({message,errors}) gövdesini OKUYOR; bu yüzden ApiError'da
 * gövdeyi döndürüp mevcut bileşen mantığını (res.success / res.errors) koruyoruz.
 */
export default async function postProfileUpdate({ requestData }: { requestData: any; token?: any }) {
    const requestBody = {
        email: requestData.email,
        password: requestData.currentPassword,
        new_password: requestData.newPassword,
        confirm_new_password: requestData.newPasswordAgain,
        first_name: requestData.firstName,
        last_name: requestData.lastName,
        country_id: requestData.countryId,
        title: requestData.title,
        dob: requestData.dob,
        phone: requestData.phone,
        address: requestData.address,
        gender: requestData.gender,
        google_id: requestData.google,
        facebook_id: requestData.facebook,
        passport: requestData.passportNumber,
        passport_issued_at: requestData.passportIssuedAt,
        passport_expires_at: requestData.passportExpiresAt,
        management_title: requestData.managementTitle,
        meta: {
            preffered_travel_styles: requestData.travelStyles,
            preffer_lodgings: requestData.lodgings,
            activities: requestData.activities,
            categories: requestData.categories,
        },
    };

    try {
        return await apiClient("/b2c/profile", {
            method: "POST",
            body: requestBody,
            auth: "sanctum",
            token: getCookie("auth-token-v3") as string,
        });
    } catch (e) {
        if (e instanceof ApiError) return e.body; // {message, errors} (422) → bileşen res.errors okur
        throw e;
    }
}

/** Profil fotoğrafı yükleme — apiv3 `POST /b2c/profile/picture` (multipart, Sanctum). */
export function postProfilePhotoUpdate({ file }: { file: any; token?: any }) {
    const body = new FormData();
    body.append("file", file);

    return apiClient("/b2c/profile/picture", {
        method: "POST",
        body,
        auth: "sanctum",
        token: getCookie("auth-token-v3") as string,
    });
}
